// Passo 1: conferimos que cada bloco é uma lista de verdade.
function montarPlaylist(...blocos) {
  for (const bloco of blocos) {
    if (!Array.isArray(bloco)) {
      throw new Error('cada bloco precisa ser uma lista');
    }
  }

  // Passo 2: lista vazia + um concat por bloco, na ordem recebida.
  return [].concat(...blocos);
}

console.log(montarPlaylist(['a', 'b'], ['c'], ['d', 'e']));
// imprime: ['a', 'b', 'c', 'd', 'e']
